// Authored short-story combat rules; original art/timing live in journey-monsters.
export const attackDamage=rank=>30+rank*8;
export const requiredHits=chapter=>3+chapter%2;
export const encounterHealth=(chapter,rank=chapter)=>attackDamage(rank)*requiredHits(chapter);
export const newEnemy=()=>({x:64,vx:0,facing:1,pose:'stand',time:0,cooldown:1500,resolved:false,targetX:25});
export function strikeEnemy(enemy,facing=1){return {...enemy,pose:'hurt',time:0,vx:facing*200,cooldown:Math.max(650,enemy.cooldown),resolved:true};}
export function stepEnemy(enemy,player,ms,width,monster,{active=true,dead=false}={}){
 const e={...enemy},dt=Math.max(0,Math.min(ms,100)),seconds=dt/1000;let attack=false;
 if(dead){if(e.pose!=='die'){e.pose='die';e.time=0;e.vx=0;}else e.time+=dt;return {enemy:e,attack};}
 if(!active)return {enemy:e,attack};
 e.time+=dt;e.cooldown-=dt;e.facing=player.x>=e.x?-1:1;
 e.x=Math.max(14,Math.min(83,e.x+e.vx*seconds/Math.max(width,1)*100));e.vx*=Math.exp(-8*seconds);
 if(e.pose==='hurt'){if(e.time>=Math.min(450,monster.poses.hurt.reduce((a,f)=>a+f.delay,0))){e.pose='stand';e.time=0;}return {enemy:e,attack};}
 if(e.pose==='attack'){
  if(!e.resolved&&e.time>=monster.impactTime){e.resolved=true;attack=true;}
  if(e.time>=monster.attackDuration){e.pose='stand';e.time=0;e.cooldown=1500;}
 }else if(e.cooldown<=0){e.pose='attack';e.time=0;e.resolved=false;e.targetX=player.x;}
 else{const distance=(player.x-e.x)/100*width;if(Math.abs(distance)>90){e.x+=Math.sign(distance)*36*seconds/Math.max(width,1)*100;e.pose='move';}else e.pose='stand';}
 return {enemy:e,attack};
}
export function enemyAttackReaches(enemy,player,width){return Math.abs(player.x-enemy.targetX)/100*width<85&&player.y<70;}
export function receiveHit(player,sourceX,amount,width){
 if(player.invulnerable>0||player.hp<=0)return player;
 const direction=player.x>=sourceX?1:-1;
 return {...player,hp:Math.max(0,player.hp-amount),invulnerable:.95,hurtTime:.45,knockbackVx:direction*300,vy:Math.max(player.vy,160)};
}
export function attackChoice(rank,mp){const cost=rank?8+rank*2:0,skill=rank>0&&mp>=cost;return {skill,cost:skill?cost:0};}
// One pending tap survives release during a cast; holding A repeats without growing a queue.
export function createAttackBuffer(){let pending=false;return {push(){pending=true;},clear(){pending=false;},take(available){if(!available||!pending)return false;pending=false;return true;}};}
